type JsonObject = { [key: string]: JsonValue };
type JsonValue = string | number | boolean | null | JsonObject | JsonValue[];

function isJsonObject(value: unknown): value is JsonObject {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function unwrapData(value: unknown): unknown {
  let current = value;
  for (let i = 0; i < 3; i += 1) {
    if (!isJsonObject(current)) return current;
    if (isJsonObject(current.order)) {
      current = current.order;
      continue;
    }
    if (isJsonObject(current.data)) {
      current = current.data;
      continue;
    }
    return current;
  }
  return current;
}

function unwrapOrderResponse(value: unknown, expectedId: number): ApiOrder | null {
  const candidate = unwrapData(value);
  if (
    !isJsonObject(candidate) ||
    Number(candidate.id) !== expectedId ||
    typeof candidate.status !== 'string'
  ) {
    return null;
  }
  return candidate as unknown as ApiOrder;
}

function unwrapArrayResponse(
  value: unknown,
  keys: readonly string[],
): unknown[] | null {
  let current = value;
  for (let depth = 0; depth < 4; depth += 1) {
    if (Array.isArray(current)) return current;
    if (!isJsonObject(current)) return null;

    const object = current;
    const nextKey = keys.find((key) => key in object);
    if (!nextKey) return null;
    current = object[nextKey];
  }
  return Array.isArray(current) ? current : null;
}

function normalizeOrderList<T extends { id: number; status: string }>(
  value: unknown,
  keys: readonly string[],
): T[] | null {
  const list = unwrapArrayResponse(value, keys);
  if (!list) return null;

  return (
    list
      .filter(isJsonObject)
      .map((order) => ({
        ...order,
        id: Number(order.id),
        status: String(order.status ?? ''),
      }))
      .filter((order) => Number.isFinite(order.id) && order.id > 0 && order.status)
  ) as T[];
}

